# owner: platform
"""Timesheet lines for a schedule, busiest workers first."""

from typing import Dict, List
from hourglass.schedule import worker_minutes
from hourglass.models import Shift
from hourglass.errors import ProjectError
from collections import Counter

# ---
def timesheet_lines(shifts: List[Shift]) -> List[str]:
    """One line per worker, most hours first."""
    _check_shifts(shifts)
    minutes = worker_minutes(shifts)
    counts = Counter(shift.worker for shift in shifts)
    names = _busiest_first(minutes)
    return [_line(name, counts, minutes) for name in names]

def _check_shifts(shifts: List[Shift]) -> None:
    if not shifts:
        raise ProjectError("no shifts to build from")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")

def _busiest_first(minutes: Dict[str, int]) -> List[str]:
    return sorted(
        minutes,
        key=lambda name: (-minutes[name], name),
    )

def _line(
    name: str, counts: Counter, minutes: Dict[str, int]
) -> str:
    count = counts[name]
    hours = minutes[name] / 60
    noun = "shift" if count == 1 else "shifts"
    return f"{name}: {count} {noun}, {hours:.1f} hours"
